return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=4; plural=(n%100==1 ? 0 : n%100==2 ? 1 : n%100==3 || n%100==4 ? 2 : 3);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Pojdite na Iskanje vtičnikov','Activate %s' => 'Aktivacija %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> zahteva namestitev in aktivacijo <strong>%2$s</strong>. <a href="%4$s">%3$s</a>','Enter your code here' => 'Tukaj vnesite svojo kodo','Add %s' => 'Dodaj %s','Remove' => 'Odstranite','Order number and receipt will be sent to this email address.' => 'Na ta e-poštni naslov bosta poslana številka naročila in potrdilo o prejemu.','Apartment, unit, building, floor, etc.' => 'Stanovanje, enota, stavba, nadstropje itd.','Shipping phone' => 'Telefon za pošiljanje','Only used for shipping-related questions.' => 'Uporablja se samo za vprašanja, povezana s pošiljanjem.','Single step' => 'Posamezen korak','Click to go to the order summary' => 'Kliknite za prehod na povzetek naročila','Cart total:' => 'Skupna košarica:','Proceed to %s' => 'Nadaljuj z %s','Proceed to contact' => 'Nadaljujte z vzpostavljanjem stika','Proceed to shipping' => 'Nadaljujte z odpošiljanjem','Proceed to billing' => 'Nadaljujte z obračunavanjem','Proceed to payment' => 'Nadaljujte s plačilom','Shipping method' => 'Način pošiljanja','Additional notes' => 'Dodatne opombe','Payment method' => 'Način plačila','Step %1$s of %2$s' => 'Korak %1$s od %2$s','Change: %s' => 'Sprememba: %s','Not selected yet.' => 'Še ni bil izbran.','Same as shipping address' => 'Enako kot naslov za pošiljanje','Same as billing address' => 'Enako kot naslov za izdajo računa','Order summary' => 'Povzetek naročila','Edit cart' => 'Urejanje vozička','Did you mean %s?' => 'Ste mislili %s?','Change email address to: {suggestion-value}' => 'Spremenite e-poštni naslov na: {suggestion-value}','This is a required field.' => 'To je obvezno polje.','This is not a valid email address.' => 'To ni veljaven e-poštni naslov.','This field does not match the related field value.' => 'To polje se ne ujema z vrednostjo povezanega polja.','The CPF number "{cpf_number}" is invalid.' => 'Številka CPF "{cpf_number}" je neveljavna.','The CNPJ number "{cnpj_number}" is invalid.' => 'Številka CNPJ "{cnpj_number}" je neveljavna.','(Required)' => '(obvezno)','Checkout Header - Desktop' => 'Najava na blagajni - namizni računalnik','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Prikaži gradnike v glavi blagajne za velike zaslone. Prikaže se samo, če uporabljate glavo blagajne vtičnika.','Checkout Header - Mobile' => 'Najava na blagajni - Mobilni','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Prikažite gradnike pod glavo blagajne za mobilne naprave. Prikaže se samo, če uporabljate glavo blagajne vtičnika.','Checkout Sidebar' => 'Bočna vrstica Checkout','Display widgets on the checkout sidebar after the order summary.' => 'Prikaži gradnike v stranski vrstici blagajne po povzetku naročila.','Checkout Order Summary' => 'Povzetek naročila na blagajni','Display widgets inside the order summary at the checkout page.' => 'Prikaži gradnike znotraj povzetka naročila na strani blagajne.','Checkout Below Place Order' => 'Checkout Spodaj Kraj naročila','Display widgets below the place order button at the checkout page.' => 'Prikaži gradnike pod gumbom za oddajo naročila na strani z blagajno.','Checkout Footer' => 'Stopka blagajne','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Prikaži gradnike v nogi blagajne. Prikaže se samo, če uporabljate nogo blagajne vtičnika.','Classic' => 'Classic','Boxed' => 'V škatli','Split' => 'Split','Minimalist' => 'Minimalistični','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Fluid Checkout in Delivery Date plugins s CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Odkrili smo, da uporabljate vtičnik Delivery & Pickup Date Time za WooCommerce (brezplačen in PRO), ki ga CodeRockz. Integracija s temi vtičniki je bila prestavljena na Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Nadgradnja na PRO','Fluid Checkout database updated successfully' => 'Podatkovna baza Fluid Checkout je bila uspešno posodobljena','The database changes where applied successfully.' => 'Spremembe podatkovne zbirke so bile uspešno uporabljene.','Dismiss' => 'Zavrnite','Fluid Checkout database update' => 'Posodobitev baze podatkov Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Potrebne so nekatere spremembe podatkovne zbirke. Kot pri vsaki posodobitvi vam priporočamo, da <strong>pred nadaljevanjem naredite popolno varnostno kopijo spletnega mesta</strong>.','Update database' => 'Posodobitev podatkovne zbirke','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout ni združljiv s postavitvijo blagajne Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout potrebuje za delovanje klasični obrazec za blagajno, ki temelji na bližnjici WooCommerce. Če za prilagajanje videza in občutka strani blagajne uporabljate orodje Divi Builder, se klasične bližnjice nadomestijo z gradniki po meri iz orodja Divi Builder za vsak del strani blagajne. Ti gradniki po meri niso združljivi s funkcijo Fluid Checkout.</p><p>Prosimo, da uredite svojo stran z blagajno in gradnike Divi Builder zamenjate z gradnikom besedila, ki vsebuje bližnjico <koda>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Urejanje strani blagajne','Read the documentation.' => 'Preberite dokumentacijo.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanizirana funkcija večstopenjske blagajne PRO mora biti onemogočena, ko uporabljate Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Pri uporabi aplikacije Fluid Checkout funkcija več korakov iz vtičnika Germanized PRO postane nepotrebna in lahko povzroči <strong>kritične napake pri obdelavi novih naročil</strong>. V nastavitvah vtičnika Germanized PRO onemogočite funkcijo večstopenjske blagajne.','Go to Germanized settings' => 'Pojdite na germanizirane nastavitve','Thanks for choosing Fluid Checkout!' => 'Hvala za izbiro Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Vtičnik uporabljate že nekaj časa. Kako vam je do zdaj všeč? <br>Prosimo, da nam na hitro podate oceno, cenimo vsako povratno informacijo, ki nas spodbuja k nadaljnjemu izboljševanju vtičnika :)','Rate the plugin' => 'Ocenite vtičnik','I need help!' => 'Potrebujem pomoč!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Nekatere funkcije WooCommerce Checkout Manager, ki jih Quadlayers morda ne bo deloval, kot je bilo pričakovano, ko ga uporabljate z Fluid Checkout. Preberite <a href="%s">našo dokumentacijo</a> za več informacij in alternativne rešitve.','Read documentation' => 'Preberite dokumentacijo','Don\'t show this again' => 'Tega ne pokažite več','Fluid Checkout PRO' => 'Preverjanje tekočin PRO','More design templates' => 'Več predlog za oblikovanje','Optimized cart page' => 'Optimizirana stran košarice','Optimized order received / thank you page' => 'Optimizirano prejeto naročilo / zahvalna stran','Edit cart contents at checkout page' => 'Urejanje vsebine košarice na strani blagajne','Account matching / user matching' => 'Ujemanje računov/uporabnikov','Trust symbols on the cart and thank you pages' => 'Simboli zaupanja v košarici in na straneh z zahvalami','More positions for the coupon code on the checkout page' => 'Več mest za kodo kupona na strani blagajne','International phone numbers' => 'Mednarodne telefonske številke','Gift messages and packing slips' => 'darilna sporočila in lističi za pakiranje','Local pickup and in-store collection' => 'Lokalni prevzem in prevzem v trgovini','EU-VAT Assistant' => 'Pomočnik za DDV EU','I already have it – Hide this offer' => 'Že imam - Skrij to ponudbo','Activated' => 'Aktivirani','Address book' => 'Naslovni imenik','Select an image' => 'Izberite sliko','Cart layout' => 'Postavitev košarice','Cart optimizations' => 'Optimizacije košarice','Enable cart page optimizations' => 'Omogočite optimizacije strani košarice','Header and footer template' => 'Predloga za glavo in nogo','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Določa, ali naj se uporabita glavi in noga strani, ki ne odvračata pozornosti, ali naj se ohranita glavi in noga trenutno aktivne teme.','Distraction free header and footer' => 'Brez motečih elementov v glavi in nogi','Theme\'s header and footer' => 'Glava in noga teme','Cart elements' => 'Elementi košarice','Make the order summary stay visible on the cart page while scrolling' => 'poskrbite, da bo povzetek naročila med pomikanjem viden na strani košarice','Coupon codes' => 'Kode kuponov','Hidden' => 'Skriti','Before the cart items section' => 'Pred razdelkom elementov košarice','Inside the cart items section' => 'V razdelku elementov košarice','After the cart items section' => 'Po razdelku Elementi v košarici','Before the shipping section' => 'Pred oddelkom za odpremo','After the shipping section' => 'Po razdelku za odpremo','Before the order summary' => 'Pred povzetkom naročila','Inside the order summary' => 'Znotraj povzetka naročila','Before the order totals' => 'Pred skupnim zneskom naročila','After the order totals' => 'Po seštevku naročil','After the order summary' => 'Po povzetku naročila','Shipping' => 'Dostava','Select position where to display the shipping costs and calculator on the cart page.' => 'Izberite položaj, kjer želite prikazati stroške dostave in kalkulator na strani košarice.','Display as a cart section' => 'Prikaži kot razdelek košarice','Cross-sells' => 'Navzkrižna prodaja','Select position where to display the cross-sells section on the cart page.' => 'Izberite položaj, kjer se na strani košarice prikaže razdelek za navzkrižno prodajo.','Before the cart actions' => 'Pred akcijami v košarici','After the cart actions' => 'Po akcijah v košarici','Layout of cross-sell items on the cart page.' => 'Postavitev predmetov navzkrižne prodaje na strani košarice.','Optimized horizontal cross-sells layout' => 'Optimizirana vodoravna postavitev navzkrižne prodaje','Theme\'s cross-sells layout' => 'Postavitev navzkrižne prodaje teme','Number of cross-sell items to display on the cart page' => 'Število elementov navzkrižne prodaje, ki se prikažejo na strani košarice','Add widget areas to the cart page' => 'Dodajanje področij gradnikov na stran košarice','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Ta področja gradnikov se uporabljajo za dodajanje simbolov zaupanja in značk zaupanja na strani košarice.','Checkout' => 'Izpisovanje','Checkout layout' => 'Postavitev blagajne','Design template' => 'Predloga za oblikovanje','Dark mode' => 'Temni način','Enable dark mode' => 'Omogočanje temnega načina','Logo image' => 'Slika logotipa','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Izberite sliko, ki se prikaže v glavi strani z blagajno. Velja samo pri uporabi glave in noge brez odvračanja pozornosti.','Header background color' => 'Barva ozadja glave','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Izberite barvo ozadja za glavo strani z blagajno. Velja samo pri uporabi glave in noge brez odvračanja pozornosti.','HTML color value. ie: #f3f3f3' => 'Vrednost barve HTML. tj: #f3f3f3','Page background color' => 'Barva ozadja strani','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Izberite barvo ozadja za stran z blagajno. Barva se uporabi za element <em>body</em>.','Footer background color' => 'Barva ozadja noge','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Izberite barvo ozadja za nogo strani z blagajno. Velja samo pri uporabi glave in noge brez odvračanja pozornosti.','Progress bar' => 'Vrstica napredka','Make the checkout progress bar stay visible while scrolling' => 'poskrbite, da bo vrstica napredka na blagajni med pomikanjem ostala vidna','Express checkout' => 'Ekspresna blagajna','Enable the express checkout section' => 'Omogočite razdelek za ekspresno blagajno','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Na blagajni prikaže razdelek za ekspresno blagajno, če imajo podprti plačilni prehodi omogočeno to funkcijo.','Display express checkout buttons in one line for larger screens' => 'Prikaz gumbov za ekspresno blagajno v eni vrstici za večje zaslone','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignoriranje dodatnih zahtevanih polj na blagajni pri plačevanju z združljivim plačilnim prehodom za ekspresno blagajno','Make the order summary stay visible while scrolling' => 'poskrbite, da povzetek naročila ostane viden med pomikanjem','Choose a background color for the order summary section.' => 'Izberite barvo ozadja za razdelek s povzetkom naročila.','Highlight the order totals row in the order summary table' => 'Označite vrstico s seštevki naročil v preglednici s povzetkom naročil.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Najbolj uporabno, kadar razdelek povzetka naročila nima poudarjene barve ozadja. Lahko se uporablja tudi za strani Košarica, Prejeto naročilo in Ogled naročila, če uporabljate Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Povezava za ukrepanje v povzetku naročila pri blagajni.','Edit cart link' => 'Uredite povezavo do košarice','Cart items count' => 'Število elementov v košarici','Link to shop page' => 'Povezava do strani trgovine','Cart items' => 'Elementi v košarici','Hide cart items errors at the checkout page' => 'Skrijte napake elementov košarice na strani blagajne','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Na vrhu strani z blagajno ne prikažite sporočila o napakah v košarici. Ko oddate obrazec za blagajno in dokončate nakup, se ta sporočila o napakah vedno prikažejo.','Place order' => 'Oddajte naročilo','Define the position to display "Place order" and terms checkbox section.' => 'Določite položaj za prikaz razdelka "Place order" in pogojev potrditvenega polja.','Some options might not be compatible with some plugins and themes.' => 'Nekatere možnosti morda ne bodo združljive z nekaterimi vtičniki in temami.','Below the payment section' => 'Pod razdelkom za plačilo','Below the order summary' => 'Pod povzetkom naročila','Both below the payment section and the order summary' => 'Pod razdelkom za plačilo in povzetkom naročila','Add widget areas to the checkout page' => 'Dodajanje področij gradnikov na stran blagajne','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Ta področja gradnikov se uporabljajo za dodajanje simbolov zaupanja in značk zaupanja na strani z blagajno.','Display the coupon codes section title' => 'Prikažite naslov razdelka s kodami kuponov','Select position where to display the coupon codes section on the checkout page.' => 'Izberite položaj, kjer se prikaže razdelek s kodami kuponov na strani blagajne.','Before the checkout steps' => 'Pred koraki na blagajni','As a substep before payment methods' => 'Kot podkorak pred plačilnimi metodami','As a substep after payment methods' => 'kot naslednji korak po plačilnih metodah','Default button style' => 'Privzet slog gumba','"Add" link button' => 'Gumb za povezavo "Dodaj"','Checkout fields' => 'Polja blagajne','Optional fields' => 'Neobvezna polja','Hide optional fields behind a link button' => 'Skrivanje neobveznih polj za gumbom za povezavo','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Priporočljivo je, da je ta možnost označena, da se zmanjša število odprtih vnosnih polj, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">preberi raziskavo</a>.','Do not hide "Address line 2" fields behind a link button' => 'Polja "Naslovna vrstica 2" ne skrivajte za gumbom za povezavo','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Priporočljivo le, če večina strank dejansko potrebuje polje "Naslovna vrstica 2" ali če je pravilen naslov za pošiljanje ključnega pomena (npr. pri dostavi hrane in drugih pokvarljivih izdelkov).','Billing address' => 'Obračunski naslov','Select position where to display the billing address section on the checkout page.' => 'Izberite položaj, v katerem želite prikazati razdelek z naslovom za izdajo računa na strani z blagajno.','As a step before shipping' => 'Kot korak pred odpremo','As a sub-step before the shipping address section' => 'Kot podkorak pred razdelkom z naslovom za pošiljanje','As a sub-step after the shipping address section' => 'Kot podkorak po razdelku z naslovom za pošiljanje','As a step after shipping' => 'Kot korak po odpremi','As a sub-step before the payment section' => 'Kot podkorak pred razdelkom o plačilu','Force billing and shipping addresses to the same (single section)' => 'Prisilite naslove za zaračunavanje in pošiljanje v isti (en sam razdelek).','Checkbox for "Same as shipping/billing address" checked by default' => 'Privzeto preverjeno potrditveno polje "Enako kot naslov za pošiljanje/obračun".','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Polje "Enako kot naslov za pošiljanje" bo privzeto označeno, ko bo najprej prikazan razdelek z naslovom za pošiljanje. <br>Ključno polje "Same as billing address" (Enako kot naslov za pošiljanje računa) bo privzeto označeno, ko bo najprej prikazan razdelek z naslovom za pošiljanje računa. <br> Priporočljivo je, da pustite to možnost označeno, saj boste tako znatno zmanjšali število odprtih vnosnih polj na blagajni, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">preberi raziskavo</a>.','Highlight the billing address section in the checkout form' => 'V obrazcu za prijavo na blagajno označite razdelek z naslovom za izdajo računa.','Shipping address' => 'Naslov za pošiljanje','Highlight the shipping address section in the checkout form' => 'V obrazcu za prijavo na blagajno označite razdelek z naslovom za pošiljanje','Shipping methods' => 'Načini pošiljanja','Choose in which position to display the shipping methods section.' => 'Izberite, v katerem položaju želite prikazati razdelek z načini pošiljanja.','Before shipping address' => 'Pred naslovom za pošiljanje','After shipping address' => 'Po naslovu za pošiljanje','Local pickup' => 'Lokalni prevzem','Removes shipping address section when a local pickup shipping method is selected.' => 'Odstrani razdelek z naslovom za pošiljanje, ko je izbran način pošiljanja z lokalnim prevzemom.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Nadomesti naslov za pošiljanje z lokacijo točke prevzema, če je izbran način pošiljanja z lokalnim prevzemom.','Choose which address to save as the shipping address for local pickup orders.' => 'Izberite, kateri naslov želite shraniti kot naslov za pošiljanje za naročila za lokalni prevzem.','Save the selected pickup location' => 'Shranjevanje izbrane lokacije prevzema','Save same as the billing address' => 'Shrani enako kot naslov za izdajo računa','Do not save any shipping address' => 'Ne shranite nobenega naslova za pošiljanje','Company name field for shipping address' => 'Polje z imenom podjetja za naslov za pošiljanje','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Spremenite vidnost polja z imenom podjetja v razdelku z naslovom za pošiljanje v obrazcu za prijavo na blagajno.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Če je polje nastavljeno kot "neobvezno", kar je privzeto stanje vidnosti, se ne bodo uporabile nobene spremembe, da bodo lahko drugi vtičniki uporabili vse potrebne spremembe.','Hidden (remove field)' => 'Skrito (odstranite polje)','Optional' => 'Izbirno','Required' => 'Zahtevano','Add shipping phone field to the checkout form.' => 'Dodajte polje za dostavni telefon v obrazec za prijavo na blagajno.','Choose in which step to display the shipping phone field.' => 'Izberite, v katerem koraku se bo prikazalo polje telefona za pošiljanje.','Contact step' => 'Korak za stik','Billing phone' => 'Telefon za obračunavanje','Add billing phone field to the checkout form.' => 'V obrazec za prijavo na blagajno dodajte polje telefona za zaračunavanje.','Choose in which step to display the billing phone field.' => 'Izberite, v katerem koraku se bo prikazalo polje za obračunski telefon.','Show country code beside the flag' => 'Prikaz kode države ob zastavi','Show an example of a valid phone number inside phone fields' => 'Prikaz primera veljavne telefonske številke znotraj polj za telefon','Do not change placeholders' => 'Ne spreminjajte nadomestnih nosilcev','Show if not defined' => 'Prikaži, če ni opredeljeno','Always show' => 'Vedno pokažite','Order notes' => 'Opombe za naročilo','Define the visibility of the additional order notes field.' => 'Opredelite vidnost polja za dodatne opombe naročila.','Gift options' => 'Možnosti daril','Allow customers to add a gift message and other gift related options to the order.' => 'Strankam omogočite, da v naročilo dodajo sporočilo o darilu in druge možnosti, povezane z darilom.','Display the gift message as part of the order details table instead of a separate section' => 'Prikaz sporočila o darilu kot del tabele s podrobnostmi naročila namesto v ločenem razdelku','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Ta možnost vpliva na stran za potrditev naročila (zahvalna stran) in podrobnosti naročila na straneh računa, e-poštnih sporočilih in pakirnih listih.','Account matching' => 'Ujemanje računov','Enable the account matching feature' => 'Omogočite funkcijo ujemanja računov','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Povežite naročila gostujoče stranke z njenim obstoječim računom, če že obstaja račun s kontaktnimi podatki stranke.','Display message when an account exists with the email address provided' => 'Prikaz sporočila, ko obstaja račun z navedenim e-poštnim naslovom','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Polja za ustvarjanje računa zamenja z obvestilom in možnostjo prijave. V nekaterih okoliščinah je priporočljivo, da ta možnost ostane onemogočena zaradi zaščite zasebnosti strank.','Dashboard' => 'Nadzorna plošča','Integrations' => 'Integracije','License keys' => 'Licenčni ključi','Visit our website for more information about our plugins and add-ons.' => 'Za več informacij o naših vtičnikih in dodatkih obiščite naše spletno mesto.','Order pay page' => 'Stran za plačilo naročila','Order pay' => 'Plačilo naročila','Enable order pay page optimizations' => 'Omogočite optimizacije strani za plačilo naročila','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Spremeni postavitev strani za plačilo naročila za obstoječa naročila, ki čakajo na plačilo s strani stranke.','Add widget areas to the order pay page' => 'Dodajanje področij gradnikov na stran za plačilo naročila','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Ta področja gradnikov se uporabljajo za dodajanje simbolov zaupanja in značk zaupanja na strani za plačilo naročila.','Thank you page & order details layout' => 'Zahvalna stran in postavitev podrobnosti naročila','Order details optimizations' => 'Optimizacije podrobnosti naročila','Enable thank you page and order details optimizations' => 'Omogočite optimizacijo zahvalne strani in podrobnosti naročila','Changes the layout of order details on the thank you page and account pages.' => 'Spremeni postavitev podrobnosti naročila na strani z zahvalo in straneh z računom.','Enable order details customizations on email notifications' => 'Omogočite prilagoditve podrobnosti naročila v e-poštnih obvestilih','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Prikaz novih razdelkov in sprememba vrstnega reda razdelkov v e-poštnih obvestilih. Slogi podrobnosti naročila v e-poštnih obvestilih ostanejo nespremenjeni.','Thank you page' => 'Zahvalna stran','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Te možnosti vplivajo na zahvalno stran, znano tudi kot stran za prejeto naročilo ali stran za potrditev naročila.','Order details layout' => 'Postavitev podrobnosti naročila','Display the order details with wide layout on the thank you page' => 'Prikaz podrobnosti naročila s široko postavitvijo na strani z zahvalo','Add widget areas to the thank you page' => 'Dodajanje področij gradnikov na zahvalno stran','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Ta področja gradnikov se uporabljajo za dodajanje simbolov zaupanja in značk zaupanja na zahvalno stran.','Order actions' => 'Ukrepi za naročanje','Choose in which position to display the order actions.' => 'Izberite, v katerem položaju želite prikazati dejanja naročila.','Inside the order overview' => 'Notranji pregled naročila','After the order overview' => 'Po pregledu naročila','After order sections' => 'Sekcije po naročilu','Order status' => 'Status naročila','Display the order status progress bar' => 'Prikažite vrstico napredka statusa naročila','Choose in which position to display the section.' => 'Izberite, v katerem položaju želite prikazati razdelek.','After the order overview and payment instructions' => 'Po pregledu naročila in navodilih za plačilo','Before the order items section' => 'Pred razdelkom elementov naročila','Inside the order items section' => 'Znotraj razdelka elementov naročila','After the order items section' => 'Po razdelku elementov naročila','On the sidebar' => 'V stranski vrstici','Order downloads' => 'Naročanje prenosov','Gift message' => 'Sporočilo o darilu','Tools' => 'Orodja','Troubleshooting' => 'Odpravljanje težav','Debug options' => 'Možnosti za odpravljanje napak','Debug mode' => 'Način za odpravljanje napak','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Uporaba načina za odpravljanje napak vpliva na zmogljivost spletnega mesta. To možnost uporabljajte samo pri odpravljanju težav.','Load unminified assets' => 'Nalaganje nezmanjšanih sredstev','Enhanced select fields' => 'Izboljšana polja za izbiro','Fix automatic zoom-in on form fields' => 'Popravek samodejnega povečanja na poljih obrazca','Set <code>font-size</code> inside form fields to 16px' => 'Nastavitev <code>velikosti črk</code> znotraj polj obrazca na 16px','Fluid Checkout' => 'Preverjanje tekočin','Settings' => 'Nastavitve','Support' => 'Podpora','(PRO)' => '(PRO)','(experimental)' => '(eksperimentalno)','Please verify your phone number.' => 'Preverite svojo telefonsko številko.','The Bluehost Plugin' => 'Vtičnik Bluehost','Custom fields' => 'Polja po meri','Enable custom shipping email field' => 'Omogočite e-poštno polje za pošiljanje po meri','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Ko je to omogočeno, se v obrazec za prijavo na blagajno doda polje elektronske pošte za pošiljanje iz vtičnika Bluehost.','Captcha Pro by BestWebSoft' => 'Captcha Pro z BestWebSoft','Captcha position' => 'Položaj Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Določite položaj za prikaz razdelka captcha. Nekateri položaji morda ne bodo delovali, odvisno od izbrane vrste captcha.','Selecting a pickup point is required before proceeding.' => 'Pred nadaljevanjem je treba izbrati točko prevzema.','Pickup point' => 'Točka prevzema','Pickup point not selected yet.' => 'Točka prevzema še ni izbrana.','Pickup point:' => 'Točka prevzema:','Mailchimp for WooCommerce' => 'Mailchimp za WooCommerce','Subscribe checkbox' => 'potrditveno polje Naročite se','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Prekličite položaj potrditvenega polja za naročanje na strani z blagajno in ga vedno prikažite v koraku za stik.','Before Shipping Address' => 'Pred naslovom za pošiljanje','(originally "%s")' => '(prvotno "%s")','After Shipping Address' => 'Po naslovu za pošiljanje','Selecting a collection point is required when shipping with FermoPoint.' => 'Pri pošiljanju s storitvijo FermoPoint je treba izbrati zbirno mesto.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Če je preverjeno, uporabnike obvesti o tipkarskih napakah v e-pošti. (Ta funkcija je bila onemogočena, ker jo ponuja Fluid Checkout. Spremembe te možnosti ne bodo veljale)','Enable Mail Check: (disabled feature)' => 'Omogoči preverjanje pošte: (onemogočena funkcija)','Carrier:' => 'Nosilec:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - Trženje e-pošte WooCommerce','Sign up checkbox position' => 'Položaj potrditvenega polja za prijavo','Move the sign up checkbox to the contact step' => 'Premaknite potrditveno polje za prijavo v korak stika','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Če je omogočeno, se potrditveno polje premakne v korak stika neodvisno od mesta prikaza, določenega v nastavitvah vtičnika Sendinblue.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Napredek na blagajni','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Izpišite razdelek korakov blagajne iz Betheme na straneh blagajne, košarice in prejetega naročila.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Drobtine','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Izpis razdelka drobtinic iz teme Fennik pri uporabi glave in noge Fluid Checkout.','Theme Go' => 'Tema Go','My account layout' => 'Postavitev mojega računa','Enable wide layout on "My account" page.' => 'Omogočite široko postavitev na strani "Moj račun".','Theme Impreza' => 'Tema Impreza','Header' => 'Naslov','Spacing for site header at the checkout page (in pixels)' => 'Razmik med glavo spletnega mesta na strani z blagajno (v pikslih)','Only applicable when using the Impreza theme header at the checkout page.' => 'Velja samo pri uporabi glave teme Impreza na strani blagajne.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Izpišite razdelek korakov blagajne iz teme Kapee na straneh blagajne, košarice in prejetega naročila.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Izpišite razdelek korakov blagajne iz teme Porto na straneh blagajne, košarice in prejetega naročila.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Izpišite razdelek korakov blagajne iz teme Pressmart na straneh blagajne, košarice in prejetega naročila.','Theme The Gem' => 'Tema dragulj','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Izhodni oddelek korakov blagajne iz teme Gem pri uporabi glave in noge Fluid Checkout.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Izhodni oddelek korakov blagajne iz teme Woodmart pri uporabi glave in noge Fluid Checkout.','Checkout options' => 'Možnosti odjave na blagajni','Disable the theme checkout options' => 'Onemogočite možnosti blagajne teme','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Možnosti prikaz slike izdelka, polje količine, gumb za odstranitev in povezava do strani izdelka, ki jih doda tema, so privzeto onemogočene.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Napredek naročila','Display order progress from the theme' => 'Prikaz napredka naročila iz teme','Display the form field labels visible on the page' => 'Prikaz oznak polj obrazca, ki so vidne na strani','It is recommended to keep this option enabled for a better user experience.' => 'Za boljšo uporabniško izkušnjo je priporočljivo, da je ta možnost omogočena.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Dodajanje dodatnih polj v obrazec za prijavo na blagajno','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'V razdelek z naslovom za pošiljanje doda dodatno polje za pošiljanje e-pošte in telefona za pošiljanje.','Go to the home page' => 'Pojdite na domačo stran','Skip to content' => 'Preskoči na vsebino','Create an account' => 'Ustvarite račun','Log in to your account' => 'Prijavite se v svoj račun','Already have an account?' => 'Že imate račun?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Prijavite se kot %1$s. <a href="%2$s">Odjavi se</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Vaše naročilo ima skupni dolgovani znesek v višini %s. Dodatno plačilo ni potrebno.','Close and continue with checkout' => 'Zapri in nadaljuj z blagajno','Continue' => 'Nadaljuj','Parcel terminal' => 'Terminal za pakete','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ta gradnik je bil nadomeščen z gradnikom Fluid Checkout. </p><p>Če uporabljate Fluid Checkout, mora biti za pravilno delovanje na strani z blagajno uporabljena izvirna bližnjica WooCommerce <code>[woocommerce_checkout]</code>.</p><p>Za več informacij obiščite dokumentacijo Fluid Checkout.</p>','Theme The7' => 'Tema The7','Additional header sections' => 'Dodatna poglavja v glavi','Output additional header sections if enabled in the theme settings.' => 'Izpis dodatnih delov glave, če je to omogočeno v nastavitvah teme.','More information' => 'Več informacij','Pick a Locker' => 'Izberite omarico','Page template' => 'Predloga strani','Use `Order confirmation` page template for block-based themes' => 'Uporabite predlogo strani `Potrditev naročila` za teme, ki temeljijo na blokih','Only applies when using a block-based theme.' => 'Uporablja se samo pri uporabi teme, ki temelji na blokih.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Obrazec za plačilo','Apply styles to the Stripe payment form fields' => 'Uporaba slogov za polja plačilnega obrazca Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Če je omogočeno, bo Fluid Checkout uporabil sloge, optimizirane za združljivost z vtičnikom. Če za polja plačilnega obrazca Stripe uporabljate sloge po meri, boste to morda želeli onemogočiti.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Izpis poglavja korakov blagajne iz teme Nyture, ko uporabljate Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Strankam omogoča, da izvedejo plačila za naročila, ki jih upravitelj trgovine ustvari ročno ali niso zaključena med blagajno.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Vtičnik WooCommerce Checkout Manager, ki ga Quadlayers ni združljiv s Fluid Checkout','Company name field for billing address' => 'Polje z imenom podjetja za naslov za izdajo računa','Change visibility for the company name field for the billing address section on the checkout form.' => 'Spremenite vidnost polja z imenom podjetja v razdelku z naslovom za obračun v obrazcu za prijavo na blagajno.','Theme Bookshelf' => 'Tematska knjižna polica','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Pri uporabi tekočega blagajniškega sistema izberite razdelek korakov blagajne iz teme Knjižna polica.','Account password' => 'Geslo računa','An account will be created with the information provided at checkout when completing the order.' => 'Račun bo ustvarjen z informacijami, ki jih boste navedli pri blagajni, ko boste zaključili naročilo.','Choose the style of the progress bar.' => 'Izberite slog vrstice napredka.','Bars' => 'Bari','Theme Ireca' => 'Tema Ireka','WooCommerce page layout' => 'Postavitev strani WooCommerce','Force wide layout on WooCommerce pages' => 'Prisilite široko postavitev na straneh WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'To zagotavlja, da vsebinski razdelek ni preozek na straneh WooCommerce, vključno s stranmi za blagajno, košarico, prejetim naročilom, plačilom naročila in računom.','WooCommerce Smart Coupons' => 'Pametni kuponi WooCommerce','Position on checkout page' => 'Položaj na strani z blagajno','Choose where to display the available coupons section on the checkout page.' => 'Izberite, kje na strani blagajne bo prikazan razdelek z razpoložljivimi kuponi.','Before the progress bar' => 'Pred vrstico napredka','After the progress bar' => 'Po vrstici napredka','Before coupon codes section' => 'Pred razdelkom kod kuponov','Format phone numbers according to the rules for each country.' => 'Telefonske številke oblikujte v skladu s pravili posamezne države.','Use precise phone number validation' => 'Uporabite natančno preverjanje veljavnosti telefonske številke','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'To je eksperimentalna funkcija in morda ne bo delovala v skladu s pričakovanji v vseh nastavitvah. Uporabljajte jo previdno.','Phone number validation types used when precise validation is enabled.' => 'Vrste potrjevanja telefonskih številk, ki se uporabljajo, ko je omogočeno natančno potrjevanje.','Mobile' => 'Mobilni','Fixed line' => 'Fiksna linija','Toll free' => 'Brezplačna telefonska številka','Or' => 'Ali','Contact' => 'Pišite na','Multi step' => 'Večstopenjski','2 columns' => '2 stolpca','1 column' => '1 stolpec','Before checkout steps' => 'Koraki pred prijavo na blagajno','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Pri uporabi postavitve blagajne <em>"1 stolpec"</em> je ta možnost vedno nastavljena na <em>"Pred koraki blagajne"</em> in velja tudi za namizni prikaz.','Position for the extra order summary section on mobile.' => 'Položaj za dodatni razdelek s povzetkom naročila v mobilnih napravah.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Možnost <em>"V glavi strani"</em> velja samo pri uporabi glave brez odvračanja pozornosti.','On the site header (requires distraction-free header)' => 'V glavi spletnega mesta (zahteva glavo brez odvračanja pozornosti)','Initial state for the expansible order summary section on mobile.' => 'Začetno stanje raztegljivega razdelka s povzetkom naročila v mobilnem telefonu.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Priporočamo, da ga zaradi regulativnih zahtev v naslednjih državah nastavite kot <em>razširjeno</em>: <strong>Nemčija</strong>, <strong>Avstrija</strong>, <strong>Švica</strong>, <strong>Nizozemska</strong>, <strong>Poljska</strong>, <strong>Belgija</strong> in <strong>Francija</strong>.','Collapsed' => 'Zrušena stran','Expanded' => 'Razširjen','Do not show' => 'Ne prikaži','yes' => 'da','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Polje za telefonsko številko za dostavo se lahko označi kot »obvezno«, če se razdelek z naslovom za izstavitev računa prikaže za razdelkom z naslovom za dostavo in je polje za telefonsko številko za izstavitev računa nastavljeno kot »obvezno«. To je potrebno, da se zagotovi, da se naslov za dostavo lahko prepiše v naslov za izstavitev računa, kadar je ta možnost izbrana; v nasprotnem primeru stranka morda ne bo mogla zaključiti postopka plačila.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Polje za telefonsko številko za izstavitev računa se lahko označi kot »obvezno«, če se razdelek z naslovom za izstavitev računa prikaže pred razdelkom z naslovom za dostavo in je polje za telefonsko številko za dostavo nastavljeno kot »obvezno«. To je potrebno, da se zagotovi, da se naslov za dostavo lahko prepiše v naslov za izstavitev računa, kadar je ta možnost izbrana; v nasprotnem primeru stranka morda ne bo mogla zaključiti postopka plačila.','Settings profiles' => 'Profilne nastavitve','Settings profile' => 'Profil nastavitev','You do not have permission to perform this action.' => 'Za to dejanje nimate dovoljenja.','You do not have permission to activate plugins.' => 'Nimate dovoljenja za aktiviranje vtičnikov.','Missing plugin.' => 'Manjka vtičnik.','Plugin activated.' => 'Vtičnik je aktiviran.','The following changes will be applied:' => 'Uporabljene bodo naslednje spremembe:','Delete leftover options' => 'Izbriši preostale možnosti','This preview has expired. Reload the admin page to start a new preview.' => 'Ta predogled je potekel. Osvežite stran za upravljanje, da začnete nov predogled.','Preview expired' => 'Predogled je potekel','Orders cannot be placed in the preview.' => 'V predogledu ni mogoče oddati naročil.','Logging in is not available in the preview.' => 'V predogledu prijava ni na voljo.','Accounts cannot be created in the preview.' => 'V predogledu ni mogoče ustvariti računov.','Requests to other sites are blocked in the preview.' => 'V predogledu so zahtevki do drugih spletnih mest blokirani.','Processing…' => 'Obdelava…','Something went wrong. Please try again.' => 'Prišlo je do napake. Poskusite še enkrat.','Activate plugin' => 'Vklopi vtičnik','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO – Celovit paket za plačilni proces','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Vse funkcije PRO + vsi dodatki, vse v eni ceni. Oblikovalske predloge, optimizirane strani košarice in potrditve naročila, usklajevanje računov ter še veliko več.','Optimized order pay page' => 'Optimizirana stran za plačilo naročila','Delayed account creation' => 'Zamuda pri ustvarjanju računa','Address autocomplete with Google Maps APIs' => 'Samodejno dopolnjevanje naslovov z API-ji Google Maps','Multiple saved addresses with the address book' => 'Več shranjenih naslovov v imeniku','EU-VAT assistant' => 'Pomočnik za DDV v EU','Hide this section' => 'Skrij ta oddelek','Learn more' => 'Več informacij','Get early access' => 'Pridobite zgodnji dostop','Activate add-on' => 'Vključi dodatek','Get more out of your checkout journey' => 'Izkoristite nakupovalno izkušnjo v celoti','Test API key' => 'Preizkus ključa API-ja','Guided setup' => 'Vodena namestitev','Options' => 'Možnosti','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Nastavite postavitev in obliko v <a href="%s">možnostih plačila</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Omogočite nakup brez registracije in/ali preglejte <a href="%s">nastavitve uporabniških računov</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Omogoči optimizirane strani <a href="%1$s">košarica</a>, <a href="%2$s">zahvala</a> in <a href="%3$s">plačilo naročila</a>.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Omogoči <a href="%s">samodejno dopolnjevanje naslovov</a> iz Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Omogočite shranjevanje več naslovov z <a href="%s">adresarjem</a>.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Preverite, ali so za temo ali druge vgrajene vtičnike na voljo kakšne <a href="%s">možnosti integracije</a>.','Missing settings tab.' => 'Manjka zavihek z nastavitvami.','Getting started' => 'Začetek','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Odlično! Vaša stran za plačilo zdaj deluje na platformi Fluid Checkout.</strong> Tukaj je nekaj korakov za začetek:','Completed' => 'Zaključeno','Send now' => 'Pošlji zdaj','Auto-detect' => 'Samodejno zaznavanje','Afrikaans' => 'afrikanski jezik','Albanian' => 'albanski','Amharic' => 'amharščina','Arabic' => 'arabščina','Armenian' => 'armenski','Azerbaijani' => 'Azerbajdžanski','Basque' => 'baskovski','Belarusian' => 'beloruski','Bengali' => 'bengalščina','Bosnian' => 'bosanski','Bulgarian' => 'bolgarski','Burmese' => 'burmanski','Catalan' => 'katalonski','Chinese' => 'kitajski','Chinese (Simplified)' => 'Kitajščina (poenostavljena)','Chinese (Hong Kong)' => 'Kitajščina (Hongkong)','Chinese (Traditional)' => 'Kitajščina (tradicionalna)','Croatian' => 'hrvaški','Czech' => 'češki','Danish' => 'danski','Dutch' => 'nizozemščina','English' => 'angleščina','English (Australian)' => 'angleščina (avstralska)','English (Great Britain)' => 'angleščina (Velika Britanija)','Estonian' => 'estonski','Farsi' => 'perzijščina','Finnish' => 'finski','Filipino' => 'filipinski','French' => 'francoščina','French (Canadian)' => 'francoščina (kanadska)','Galician' => 'galicijski','Georgian' => 'gruzijski','German' => 'nemščina','Greek' => 'grški','Gujarati' => 'gudžaratski jezik','Hebrew' => 'hebrejščina','Hindi' => 'hindijščina','Hungarian' => 'madžarski','Icelandic' => 'islandski','Indonesian' => 'indonezijski','Italian' => 'italijanski','Japanese' => 'Japonščina','Kannada' => 'kannada','Kazakh' => 'kazahski','Khmer' => 'kmerščina','Korean' => 'korejščina','Kyrgyz' => 'Kirgiški','Lao' => 'Laoški','Latvian' => 'latvijščina','Lithuanian' => 'litovščina','Macedonian' => 'makedonski','Malay' => 'malajščina','Malayalam' => 'malajalamščina','Marathi' => 'maratščina','Mongolian' => 'mongolski','Nepali' => 'nepalščina','Norwegian' => 'norveški','Polish' => 'poljščina','Portuguese' => 'portugalščina','Portuguese (Brazil)' => 'portugalščina (Brazilija)','Portuguese (Portugal)' => 'portugalščina (Portugalska)','Punjabi' => 'pandžabščina','Romanian' => 'romunski','Russian' => 'ruščina','Serbian' => 'Srbski','Sinhalese' => 'singalščina','Slovak' => 'slovaški','Slovenian' => 'slovenščina','Spanish' => 'španščina','Spanish (Latin America)' => 'španščina (Latinska Amerika)','Swahili' => 'svahili','Swedish' => 'Švedščina','Tamil' => 'Tamilščina','Telugu' => 'telugu','Thai' => 'tajski','Turkish' => 'turški','Ukrainian' => 'ukrajinski','Urdu' => 'urdujščina','Vietnamese' => 'vietnamščina','Zulu' => 'Zulu','Google address autocomplete' => 'Samodejno dopolnjevanje naslovov v Googlu','Google Places API version' => 'Različica API-ja Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Izberite, katero različico vmesnika API Google Places želite uporabljati. Priporočamo, da čim prej preidete na novi vmesnik API Places.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Priporočamo uporabo »Places API (New)«, saj bo Google s 1. marcem 2025 različico »Places API (Legacy)« preklopil v status »Legacy«, kar pomeni, da te storitve ne boste več mogli omogočiti za nove API-ključe in da ta različica API-ja sčasoma ne bo več na voljo. Obstoječi računi, ki že uporabljajo API v statusu »Legacy«, bodo lahko še naprej delovali brez motenj.','(Recommended)' => '(Priporočeno)','Google API key' => 'Ključ API-ja Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Vnesite svoj ključ API-ja Google in s pomočjo gumba za testiranje preverite, ali deluje na tej spletni strani. Prepričajte se, da je ključ veljaven in dovoljen za vašo domeno, sicer se lahko polje za naslov blokira, kar bo strankam onemogočilo zaključek naročil.','Enable Google address autocomplete' => 'Omogoči samodejno dopolnjevanje naslovov v Googlu','Enable address autocompletion using the Google Maps APIs.' => 'Omogočite samodejno dopolnjevanje naslovov z uporabo API-jev Google Maps.','Google API language' => 'Jezik Google API','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Ta jezik se bo uporabljal za prikaz predlogov naslovov iz API-ja Google Places, naslovi pa se bodo v tem jeziku tudi samodejno dopolnjevali.','Result types' => 'Vrste rezultatov','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Pustite prazno, da se sprejmejo vsi tipi rezultatov, kar ponavadi prinese boljše ujemanje rezultatov. <a href="%s" target="_blank">Za več podrobnosti glejte dokumentacijo</a>. <br>Izberite do 5 vrst rezultatov iskanja naslovov, ki naj se prikažejo v poljih za samodejno dopolnjevanje naslovov. <br>Obiščite dokumentacijo Google Maps, da izveste več o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podprtih vrstah</a>.','Result types (Legacy API)' => 'Vrste rezultatov (stari API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Kateri tip rezultatov iskanja naslovov naj se prikaže pri uporabi vmesnika Places API (Legacy). <br>Oglejte si dokumentacijo stare različice Google Places API, da izveste več o <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">podprtih vrstah</a>.','Company fields' => 'Polja podjetja','Enable autocomplete for the company name if available' => 'Omogoči samodejno dopolnjevanje imena podjetja, če je na voljo','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Omogoči samodejno dopolnjevanje polja »podjetje« s podatki o imenu podjetja, ko jih vrnejo vmesniki API storitve Google Maps.','Business search' => 'Iskanje podjetij','Enable search for businesses in the company field' => 'Omogoči iskanje podjetij v polju »Podjetje«','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Omogoči prikaz predlogov naslovov, povezanih s podjetjem, med vnašanjem v polje »Podjetje«, nato pa samodejno dopolni vsa polja za naslove, ko je izmed predlogov izbrano podjetje.','Company result types' => 'Vrste poslovnih rezultatov','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Izberite do 5 vrst rezultatov iskanja naslovov, ki naj se prikažejo pri samodejnem dopolnjevanju polj podjetja. <br>Priporočena vrednost je <code>podjetje</code>, ki vključuje večino vrst podjetij. <br>Če polje pustite prazno, se sprejmejo vse vrste rezultatov, vključno z rezultati, ki niso povezani s podjetji. <br>Obiščite dokumentacijo Google Maps, da izveste več o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podprtih vrstah</a>.','Google logo' => 'Logotip Googla','Show text and logo "Powered by Google"' => 'Prikaži besedilo in logotip »Powered by Google«','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Če je ta možnost izbrana, se bosta besedilo in logotip »Powered by Google« prikazala na dnu okna s predlogi za samodejno dopolnjevanje naslova.','Brasil API address autocomplete' => 'Samodejno dopolnjevanje naslovov v Braziliji prek API-ja','Brasil API' => 'API za Brazilijo','Enable Brasil API address autocomplete for CEP fields' => 'Omogoči samodejno dopolnjevanje naslovov prek API-ja Brasil za polja CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Uporabite API Brasil za pridobivanje in samodejno izpolnjevanje naslovov prek polja CEP/poštna številka. Velja le za brazilske naslove.','API version' => 'Različica API-ja','Choose which version of the Brasil API CEP method to use.' => 'Izberite, katero različico metode CEP v API-ju Brasil želite uporabiti.','Address book migration' => 'Prenos imenika','WooCommerce addresses' => 'Naslovi WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopirajte obstoječe naslove za dostavo in zaračunavanje iz WooCommerce v imenik naslovov strank.','Enable the address book feature' => 'Vklopite funkcijo imenika','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Omogočite strankam, da shranijo več naslovov in določijo privzeti naslov, ki se bo uporabljal za dostavo in zaračunavanje.','Address labels' => 'Nalepke z naslovi','Allow customers to add a custom label for each address' => 'Omogočite strankam, da za vsak naslov dodajo lastno oznako','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Oznake naslovov strankam olajšajo razlikovanje med shranjenimi naslovi (npr.: »Mamin dom«). Oznake naslovov so zasebne in se ne prikazujejo niti ne natisnejo na strani s podrobnostmi naročila ali na računih.','Display layout' => 'Razpored prikaza','Choose how saved addresses are displayed at checkout and on the cart.' => 'Izberite, kako se bodo shranjeni naslovi prikazovali ob zaključku nakupa in v košarici.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Uporablja se ob zaključku nakupa in v košarici. Pri shranjenih naslovih na strani računa se vedno uporablja razporeditev s karticami.','Address cards' => 'Vizitke','Address list' => 'Seznam naslovov','Dropdown field' => 'Polje s spustnim menijem','Address search' => 'Iskanje naslova','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Prikaži filter za iskanje naslovov na uporabniškem vmesniku, če ima stranka na voljo vsaj to število shranjenih naslovov.','Not used when display layout is set to dropdown field.' => 'Ne uporablja se, če je razpored zaslona nastavljen na spustno polje.','Addresses' => 'Naslovi','Enable cart page optimizations to see more options' => 'Omogočite optimizacije strani z nakupovalno košarico, da si ogledate več možnosti','Sticky order summary' => 'Povzetek naročila, ki ostane na vrhu strani','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Izberite mesto, kjer naj se na strani košarice prikaže razdelek s kodami kuponov. To velja le, če je omogočena košarica AJAX in če je v nastavitvah WooCommerce omogočena uporaba kod kuponov.','Layout of cross-sell' => 'Shema navzkrižne prodaje','Cross-sells displayed' => 'Prikazane dopolnilne prodaje','Items' => 'Izdelki','Cart page optimization' => 'Optimizacija strani z košarico','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Poskrbite, da bo vaš nakupovalni koš imel enako pregledno in na konverzijo usmerjeno postavitev kot vaš postopek plačila.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Prilagodite postavitev košarice strani za zaključek nakupa, da bo nakupna izkušnja dosledna.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Košarico je treba v ozadju vedno posodabljati, pri spremembi količin pa se stran ne sme v celoti ponovno naložiti.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Kode kuponov, informacije o dostavi in dodatne ponudbe umestite točno tja, kjer prinašajo najboljše rezultate.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Poskrbite, da bo povzetek naročila viden tudi med pomikanjem po strani, in dodajte simbole zaupanja tam, kjer kupci potrebujejo zagotovilo.','Columns' => 'Stolpci','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Pri uporabi postavitve <em>»1 stolpec«</em> s predlogo <em>»Split«</em> se desni stolpec prikaže le, če je območje za widgete v stranskem pasu strani aktivno (stranski pas pri plačilu, stranski pas v košarici ali stranski pas ob prejemu naročila). V nasprotnem primeru stran ostane enostolpčna s slogi »Split«.','Split column background' => 'Razdeljeno ozadje stolpca','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Izberite barvo ozadja za sekundarni stolpec v postavitvi »Split«. Če polje pustite prazno, se bo uporabila barva ozadja povzetka naročila.','Page templates' => 'Predloge strani','Checkout template' => 'Predloga za zaključek nakupa','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Priporočljivo za zmanjšanje motenj ob zaključku nakupa. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Preberite raziskavo o opustitvi nakupnih košaric</a>.','Sticky progress bar' => 'Lepilni kazalnik napredka','Progress bar style' => 'Slog kazalnika napredka','Order totals' => 'Skupni zneski naročil','Background color' => 'Barva ozadja','Action link' => 'Povezava za ukrepanje','Mobile order summary' => 'Povzetek mobilnega naročila','Mobile initial state' => 'Začetno stanje mobilne naprave','Enable editing cart items at checkout' => 'Omogoči urejanje artiklov v košarici ob zaključku nakupa','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Omogočite strankam, da na strani za plačilo spremenijo količine izdelkov ali odstranijo izdelke.','Cart item errors' => 'Napake pri izdelkih v košarici','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Velja le, če je koda kupona prikazana kot ločen razdelek na straneh za plačilo ali v košarici ter če je uporaba kod kuponov omogočena v nastavitvah WooCommerce.','Coupon codes position' => 'Mesto za kodice kuponov','Apply coupon button' => 'Gumb »Uporabi kupon«','Select style of the "apply coupon" button.' => 'Izberite slog gumba »Uporabi kupon«.','Address line 2' => 'Naslovna vrstica 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ta nastavitev velja tako za razdelek »Checkout« kot za razdelek »Lokalni prevzem«. V razdelku »Lokalni prevzem« določa tudi, ali se izbirnik »Pošiljanje/Prevzem« prikaže znotraj razdelka z načini dostave (pred naslovom) ali kot ločen razdelek (za njim).','Customer accounts' => 'Strankini računi','Guest checkout' => 'Nakup kot gost','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Možnosti za nakup kot gost, prijavo in ustvarjanje računa na strani nastavitev »Računi« v WooCommerce. Zaradi vaše udobnosti se te možnosti upravljajo tukaj, tako da lahko za vsak profil nastavitev uporabite različne vrednosti.','Allow customers to checkout without an account' => 'Omogočite strankam, da opravijo nakup brez računa','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Priporočeno</strong>, da se od strank med zaključkom nakupa ne zahteva, da ustvarijo račun ali se prijavijo, kar lahko zniža stopnje konverzije.','When disabled, customers must log in or create an account to complete the purchase.' => 'Če je ta možnost onemogočena, se morajo stranke prijaviti ali ustvariti račun, da lahko zaključijo nakup.','Login at checkout' => 'Prijava ob zaključku nakupa','Enable log-in during checkout' => 'Omogoči prijavo med zaključevanjem naročila','Show a link for returning customers to log in from the checkout page.' => 'Na strani za zaključek nakupa prikaži povezavo, prek katere se lahko stalni kupci prijavijo.','Account creation' => 'Ustvarjanje računa','Allow customers to create an account during checkout' => 'Omogočite strankam, da si med zaključevanjem nakupa ustvarijo račun','Allow customers to create an account from the My account page' => 'Omogočite strankam, da si ustvarijo račun na strani »Moj račun«','Customers can register a new account from the My account page.' => 'Stranke lahko ustvarijo nov račun na strani »Moj račun«.','Username' => 'Uporabniško ime','Generate from customer\'s name' => 'Ustvari na podlagi imena stranke','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Priporočeno</strong>, da se strankam med zaključkom nakupa ne zahteva izbira uporabniškega imena, kar lahko zniža stopnje konverzije.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Uporabniško ime se ustvari na podlagi imena stranke ali, če imena ni mogoče uporabiti, na podlagi e-poštnega naslova.','Password' => 'Geslo','Send password setup link' => 'Pošlji povezavo za nastavitev gesla','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Priporočeno</strong>, da se od strank med zaključevanjem nakupa ne zahteva nastavitev gesla, kar lahko zniža stopnjo konverzije.','Customers receive an email to create their password securely.' => 'Stranke prejmejo e-poštno sporočilo, v katerem lahko varno ustvarijo svoje geslo.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Registriranim strankam omogočite, da zaključijo nakup brez prijave, naročilo pa se poveže z njihovim obstoječim računom, če se kontaktni podatki ujemajo.','Existing account message' => 'Sporočilo o obstoječem računu','Let customers create an account after placing their order, from the thank you page.' => 'Omogočite strankam, da si po oddaji naročila ustvarijo račun na strani z zahvalo.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Možnosti v tem razdelku so na voljo, če sta omogočena plačilo kot gost in usklajevanje računov. Omogočite obe zgoraj navedeni funkciji, da nastavite odloženo ustvarjanje računa.','Enable delayed account creation' => 'Omogoči odloženo ustvarjanje računa','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Omogoči odloženo ustvarjanje računa, kadar sta omogočena tako nakup kot gost kot tudi usklajevanje računov.','Section position' => 'Položaj oddelka','Before customer details section' => 'Pred razdelkom s podatki o stranki','After customer details section' => 'Po razdelku s podatki o stranki','Account creation benefits' => 'Prednosti ustvarjanja računa','Leaving the field empty will display the default text.' => 'Če polje pustite prazno, se bo prikazalo privzeto besedilo.','Inline buttons' => 'Gumbi v besedilu','Required fields' => 'Obvezna polja','Enable gift message fields at checkout' => 'Omogoči polja za sporočilo ob darilu ob zaključku nakupa','Expanded gift message' => 'Podrobnejše sporočilo ob darilu','Display gift message field always expanded' => 'Polje za vnos darilnega sporočila naj bo vedno razširjeno','Gift message in order details' => 'Sporočilo ob darilu v podrobnostih naročila','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'V tem razdelku trenutno ni na voljo nobenih integracij. Možnosti, povezane z vsakim vtičnikom in temo, se bodo tukaj prikazale šele, ko bo zadevni vtičnik ali tema aktiviran/-a.','Phone fields' => 'Polja za telefonske številke','Field visibility' => 'Vidljivost na terenu','Field position' => 'Položaj na igrišču','Phone country code & validation' => 'Koda države za telefonske številke in preverjanje veljavnosti','Country' => 'Država','Enable country on phone fields' => 'Omogoči izbiro države v poljih za telefon','Filter countries for shipping or billing' => 'Filtriranje držav za dostavo ali zaračunavanje','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Izbirnik države v vsakem polju za telefonsko številko omejite na države, ki so v vaši trgovini dovoljene za dostavo ali zaračunavanje.','Validation' => 'Preverjanje veljavnosti','Enable simple validation based on country rules' => 'Omogoči preprosto preverjanje veljavnosti na podlagi pravil posameznih držav','Checks that the phone number is valid for the selected country, including country code and length.' => 'Preveri, ali je telefonska številka veljavna za izbrano državo, vključno z državno kodo in številom mest.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Strožji pregled, ali je številka veljavna mobilna, fiksna ali druga vrsta številke, ki je sprejemljiva za izbrano državo. Lahko se zavrnejo nekatere veljavne številke.','Validation types' => 'Vrste validacije','Placeholders' => 'Zamenljivki','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Trenutno ni nobenih licenčnih ključev za upravljanje. Licenčni ključi se bodo tukaj prikazali, ko bo aktiven licenciran vtičnik ali dodatek Fluid Checkout.','Default delivery type' => 'Privzeti način dostave','Choose which delivery type will be selected by default.' => 'Izberite, kateri način dostave bo privzeto izbran.','Shipping zone fields' => 'Polja za poštne območja','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Izberite, katera polja se bodo prikazovala v filtrih za območja dostave pri prevzemu na kraju samem. Če polje pustite prazno, se prikažejo vse razpoložljive možnosti.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Ta polja se bodo prikazala kot filter za načine dostave z lokalnim prevzemom. Nekatera polja se lahko kljub temu prikažejo ob zaključku naročila, čeprav tukaj niso izbrana, če jih združljivi vtičniki potrebujejo za pravilno delovanje.','Order shipping address' => 'Naslov za dostavo naročila','Order pay page optimization' => 'Optimizacija strani za plačilo naročila','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Neplačanim naročilom dodelite enako pregledno in na konverzijo usmerjeno postavitev kot pri zaključku nakupa.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizirajte postavitev strani za plačilo naročil, za katera je plačilo še v teku.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Prilagodite izkušnjo plačila naročila svojemu postopku plačila, da zagotovite dosledno nakupno izkušnjo.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Dodajte simbole zaupanja in oznake tam, kjer kupci pred plačilom potrebujejo zagotovilo.','Thank you page optimization' => 'Optimizacija strani z zahvalo','Make the thank you page and order details clearer for customers after they buy.' => 'Stran z zahvalo in podrobnosti o naročilu morajo biti za stranke po nakupu bolj jasne.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizirajte stran z zahvalo in podrobnosti o naročilu na računu z jasnejšo postavitvijo.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Prikaži napredek stanja naročila, ukrepe, prenose in opombe tam, kjer je to primerno.','Customize order details sections on email notifications.' => 'Prilagodite razdelke s podrobnostmi naročila v e-poštnih obvestilih.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Dodajte simbole zaupanja in značke tam, kjer kupci po nakupu potrebujejo zagotovilo.','Email notifications' => 'Obvestila po e-pošti','Enable thank you page and order details optimizations to see more options' => 'Omogočite optimizacijo strani z zahvalo in podrobnosti naročila, da si ogledate več možnosti','Use wide layout on thank you page' => 'Na strani z zahvalo uporabite široko postavitev','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Te nastavitve vplivajo na stran z zahvalo, prikaz podrobnosti naročila na straneh računa ter na e-poštna obvestila.','Save settings' => 'Shrani nastavitve','Docs' => 'Dokumenti','Cart' => 'Košarica','Thank you' => 'Hvala','Address autocomplete' => 'Samodejno dopolnjevanje naslova','Trust badges' => 'Znak zaupanja','You do not have permission to save these settings.' => 'Nimate dovoljenja za shranjevanje teh nastavitev.','Invalid save request.' => 'Neveljavna zahteva za shranjevanje.','Your settings have been saved.' => 'Vaše nastavitve so bile shranjene.','Saving...' => 'Shranjevanje...','Settings could not be saved. Please try again.' => 'Nastavitev ni bilo mogoče shraniti. Poskusite še enkrat.','Dismiss notice' => 'Zaprite obvestilo','Open settings menu' => 'Odpri meni z nastavitvami','Close settings menu' => 'Zapri meni nastavitev','Preview' => 'Predogled','Expand preview' => 'Razširi predogled','Collapse preview' => 'Zloži predogled','Show header and footer' => 'Prikaži glavo in nogo strani','Hide header and footer' => 'Skrij glavo in nogo strani','Page preview' => 'Predogled strani','Preview viewport' => 'Predogledno okno','Tablet' => 'Tablični računalnik','Desktop' => 'Namizje','Preview width' => 'Širina predogleda','Decrease width' => 'Zmanjšaj širino','Preview width in pixels' => 'Širina predogleda v piksljih','Increase width' => 'Povečaj širino','Preview as' => 'Predogled kot','Guest' => 'Gost','Logged in' => 'Prijavljen','Preview page' => 'Stran s predogledom','Expand preview for a closer look' => 'Razširite predogled, da si ga ogledate podrobneje','Available with %s.' => 'Na voljo z %s.','Turn them on' => 'Vklopite jih','Optimizations for this page are turned off. %s to preview the page.' => 'Optimizacije za to stran so izklopljene. %s za predogled strani.','%s preview' => '%s predogled','Isolated session · nothing is saved' => 'Osamljena seja · nič se ne shrani','Usage tracking' => 'Sledenje uporabi','Plugin settings' => 'Nastavitve vtičnika','Coming soon' => 'Kmalu na voljo','Utilities' => 'Komunalne storitve','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Namesto <code>select2</code> uporabite spustne menije <code>TomSelect</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect je preprostejši izbirni element s spustnim menijem, ki je manj nagnjen k napakam kot Select2, hkrati pa ponuja enako funkcionalnost.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Vzpostavi velikost pisave v poljih obrazca na 16px na straneh, ki jih je optimiziral ta vtičnik, da se prepreči samodejno povečanje slike pri uporabi polj obrazca na manjših napravah.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari in drugi brskalniki lahko na mobilnih napravah samodejno povečajo prikaz, da je besedilo lažje berljivo, kadar je velikost pisave manjša od 16px.','Enable script processing tracking on the browser console.' => 'Vklopite sledenje izvajanja skriptov v konzoli brskalnika.','Unminified assets' => 'Neminificirane datoteke','Google Maps scripts' => 'Skripti za Google Maps','Do not remove duplicate Google Maps scripts' => 'Ne odstranjujte podvojenih skriptov Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Če je ta možnost omogočena, se podvojeni skripti Google Maps NE bodo odstranili, kar lahko povzroči napake in težave z delovanjem. To možnost uporabljajte le med odpravljanjem težav.','Widget areas' => 'Prostori za widgete','Last step on mobile' => 'Zadnji korak na mobilni napravi','Display widgets only at last step on mobile' => 'Na mobilnih napravah prikaži widgete šele v zadnjem koraku','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Prikaži widgete z znakom zaupanja pri plačilu le ob ogledu zadnjega koraka plačila na mobilnih napravah','Standard' => 'Standard','VAT number field' => 'Polje za številko DDV','Add a VAT number field to the billing form.' => 'V obrazec za izstavitev računa dodajte polje za številko DDV.','Field label' => 'Oznaka polja','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Nastavite oznako polja za številko DDV (npr. »Številka DDV«). Na večjezičnih spletnih straneh je bolje, da to polje pustite prazno in prevedete izvirni niz.','VAT Number' => 'Številka DDV','EU-VAT' => 'DDV v EU','Enable the VAT number field to see more options' => 'Omogočite polje za številko DDV, da si ogledate več možnosti','VAT validation' => 'Preverjanje veljavnosti DDV','Validate VAT number field for EU-VAT during checkout' => 'Preverjanje veljavnosti polja za številko DDV za DDV v EU med zaključkom nakupa','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Preveri, ali je navedena številka DDV veljavna številka DDV, registrirana v evropski bazi podatkov VIES (sistem za izmenjavo podatkov o DDV).','Shop VAT number' => 'DDV-številka trgovine','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'DDV-številka trgovine, ki se uporablja za zahtevo za potrditev DDV v EU in je natisnjena na računih. <br><strong>Močno priporočamo, da dodate DDV-številko svoje trgovine</strong>, saj v nasprotnem primeru rezultati poizvedbe v sistemu VIES morda ne bodo veljavni za računovodske namene. <br>Npr.: <code>ATU99999999</code> ali <code>EE999999999</code>.','Reverse charge' => 'Mehanizem obrnjene davčne obveznosti','Apply reverse charge mechanism' => 'Uporabi mehanizem obrnjene davčne obveznosti','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Davčno stopnjo nastavite na nič in na računih prikažite »Prenos davčne obveznosti«, če je davčna številka stranke veljavna. Glede na državo, v kateri se nahaja trgovina, je morda potrebno uporabiti drugačno besedilo za »Prenos davčne obveznosti«.','Same country' => 'Ista država','Apply reverse charge mechanism for transactions in the shop country:' => 'Za transakcije v državi, kjer se nahaja trgovina, uporabite mehanizem obrnjene davčne obveznosti:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Omogoča uporabo mehanizma obrnjene davčne obveznosti za transakcije med podjetji v isti državi kot trgovina.','Reverse charge exceptions' => 'Izjeme pri obrnjeni davčni obveznosti','Select additional countries to skip applying the reverse charge mechanism.' => 'Izberite dodatne države, v katerih se mehanizem obrnjene davčne obveznosti ne bo uporabljal.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Za naročila iz teh držav bodo zaračunani davki, tudi če je navedena veljavna številka DDV.','Reverse charge label on invoices' => 'Oznaka o obrnjeni davčni obveznosti na računih','Set the label of "reverse charge" on the checkout page and order details.' => 'Na strani za plačilo in v podrobnostih naročila nastavite oznako »obratna obdavčitev«.','Reverse charge text on invoices' => 'Besedilo o obrnjeni davčni obveznosti na računih','Set the label of "reverse charge" text on invoices.' => 'Nastavite oznako besedila »obratna obdavčitev« na računih.','Tax to be paid on reverse charge basis' => 'Davek, ki ga je treba plačati po načelu obrnjene davčne obveznosti','Company name' => 'Ime podjetja','Autocomplete company name from VAT number' => 'Samodejno dopolnjevanje imena podjetja na podlagi številke DDV','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Vnesite ime podjetja za izstavitev računa na podlagi veljavne številke DDV, ki jo je posredoval stranka.','Company name editing' => 'Urejanje imena podjetja','Allow editing of auto-filled company name' => 'Omogoči urejanje samodejno vnesenega imena podjetja','When enabled, customers can change the company name associated with the provided VAT number.' => 'Ko je ta možnost omogočena, lahko stranke spremenijo ime podjetja, povezano z navedeno številko DDV.','EU-VAT for digital goods' => 'DDV v EU za digitalne izdelke','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Od 1. januarja 2015 so bile sprejete spremembe predpisov EU o DDV v zvezi z digitalnimi izdelki, ki zadevajo izključno transakcije med podjetji in potrošniki (B2C). DDV na digitalne izdelke je treba izračunati na podlagi lokacije kupca, pri čemer je treba zbrati ustrezne dokaze (IP-naslov in naslov za izstavitev računa).','Tax classes for digital goods' => 'Davčni razredi za digitalno blago','Select some tax classes' => 'Izberite nekaj davčnih razredov','Location evidence' => 'Dokazi o lokaciji','Collect customer\'s location evidence' => 'Zberite dokaze o lokaciji stranke','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Shrani IP-naslov in ga preveri glede na naslov za izstavitev računa stranke. Stranka mora potrditi svoj naslov za izstavitev računa tako, da na strani za zaključek nakupa označi polje, če se država na naslovu za izstavitev računa in IP-naslov ne ujemata.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'To nastavitev upravljate v Fluid Checkout. <a href="%s">Spremenite jo v nastavitvah uporabniških računov</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'To nastavitev upravljate v Fluid Checkout. Spremenite jo v meniju Fluid Checkout > Strankini računi.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ta možnost se upravlja v Fluid Checkout. Ko je Fluid Checkout aktiviran, je naslov za dostavo vedno nastavljen na »Privzeto na naslov za dostavo stranke«. Stranke lahko med zaključevanjem naročila še vedno navedejo drugačne naslove za dostavo in zaračunavanje.<br><br>Možnost, da se privzeti naslov za zaračunavanje nastavi tako, da je enak naslovu za dostavo, je na voljo v <a href="%s">nastavitvah Fluid Checkout</a>.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ta možnost se upravlja v Fluid Checkout. Ko je Fluid Checkout aktiviran, je naslov za dostavo vedno nastavljen na »Privzeto na naslov za dostavo stranke«. Stranke lahko med plačilom še vedno navedejo drugačne naslove za dostavo in zaračunavanje.<br><br>Možnost, da se privzeti naslov za zaračunavanje nastavi tako, da je enak naslovu za dostavo, je na voljo v WooCommerce > Nastavitve > Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Te nastavitve so bile premaknjene v WP Admin > Fluid Checkout > Nastavitve.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Ta zavihek »Nastavitve WooCommerce« je zastarel in bo v različici Fluid Checkout 6.0 odstranjen.','Go to settings page' => 'Pojdi na stran z nastavitvami','Hide this tab permanently' => 'Trajno skrij to zavihko','Close' => 'Zapri','PRO feature' => 'Funkcija PRO','Other plugins' => 'Drugi vtičniki','Install add-on' => 'Namesti dodatek','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Pridobite %2$s</a>, da odklenete te možnosti.','Add-on' => 'Dodatek','View documentation' => 'Oglej si dokumentacijo','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Za pošiljanje zahtevkov se zahteva, da je uporabnik prijavljen v WordPress. Če želite uporabiti podatke trenutnega uporabnika, izpustite parameter user_id; če pa želite nasloviti drug račun, vnesite user_id, če ima klicatelj pravico do urejanja tega uporabnika (pristojnost edit_user). Neavtentificirani zahtevki vrnejo napako fc_api_forbidden. Neveljaven user_id vrne napako fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 z { "data": { ... } }, ko obdelovalnik vrne vsebino.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 z { "success": true }, kadar ni vsebine (na primer pri DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Napake vrnejo JSON-odziv z napako WordPress REST iz razreda WP_Error (koda, sporočilo, data.status). Kode v omrežju uporabljajo predpono fc_api_*.','Forbidden access.' => 'Dostop prepovedan.','Target user was not found.' => 'Ciljni uporabnik ni bil najden.','This feature is not available.' => 'Ta funkcija ni na voljo.','A required address field is missing.' => 'Manjka obvezno polje za naslov.','Postcode or ZIP is invalid.' => 'Poštna številka ali ZIP ni veljavna.','Phone number is invalid.' => 'Telefonska številka je neveljavna.','State or county is invalid.' => 'Država ali okrožje ni veljavno.','Country is invalid or has no address fields.' => 'Država ni veljavna ali nima polj za naslov.','The request could not be processed.' => 'Zahtevka ni bilo mogoče obdelati.','Back to previous step' => 'Nazaj na prejšnji korak','Skip to settings' => 'Preskoči na nastavitve','Start over and return to the first guided setup step' => 'Začnite znova in se vrnite na prvi korak vodene nastavitve','Start over' => 'Začni znova','Please complete all sub-steps before continuing.' => 'Preden nadaljujete, prosimo, opravite vse podkorake.','Expand' => 'Razširi','Collapse' => 'Zloži','Skip' => 'Preskoči','Mark as complete' => 'Označi kot zaključeno','Mark as incomplete' => 'Označi kot nedokončano','View full-size image: %s' => 'Oglej si sliko v polni velikosti: %s','Full-size setup guide image' => 'Slika s celotnim navodili za namestitev','Close image' => 'Zapri sliko','Fluid Checkout Guided Setup' => 'Vodena namestitev sistema Fluid Checkout','All set' => 'Vse je pripravljeno','You do not have permission to access this page.' => 'Nimate dovoljenja za dostop do te strani.','Go to step %1$d: %2$s' => 'Pojdi na korak %1$d: %2$s','Finish & go to settings' => 'Dokončaj in pojdi v nastavitve','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Spremenite nastavitev vidnosti polja za telefonsko številko za zaračunavanje iz prejšnje vrednosti, da bo v skladu s konvencijami WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Posodobite možnost vidnosti polja za telefonsko številko za dostavo, tako da se stara vrednost prilagodi konvencijam WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Nastavitev barve ozadja povzetka naročila prenesite v novo možnost barve ozadja sekundarnega stolpca v zasnovi »Split«.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Pri uporabi vtičnika Biteship je funkcija »izboljšana izbira polj« vedno onemogočena.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pri uporabi vtičnika German Market je položaj gumba za oddajo naročila vedno nastavljen na »Pod povzetkom naročila«. Ta vtičnik namreč zahteva, da se gumb za oddajo naročila in potrditvena polja za pravne pogoje prikažejo pod povzetkom naročila.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pri uporabi vtičnika Germanized za WooCommerce je položaj gumba za oddajo naročila vedno nastavljen na »Pod povzetkom naročila«. Ta vtičnik namreč zahteva, da se gumb za oddajo naročila in potrditvena polja s pravnimi informacijami prikažejo pod povzetkom naročila.','Edit pickup locations' => 'Uredi prevzemna mesta','Use local pickup label from WooCommerce settings' => 'Uporabi etiketo za prevzem na kraju samem iz nastavitev WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Če je ta možnost omogočena, se oznaka možnosti prevzema ob zaključku nakupa ujema z naslovom iz nastavitev lokacije prevzema v WooCommerce. Če je onemogočena, oznaka uporablja prevodljivo besedilo »Lokalni prevzem« iz Fluid Checkout.','Migration class %s must implement get_migration_steps().' => 'Razred migracije %s mora implementirati metodo get_migration_steps().','Migration class %s returned an empty get_migration_steps() list.' => 'Razred migracije %s je vrnil prazen seznam get_migration_steps().','Checkout design customization' => 'Prilagajanje videza blagajne','Make your checkout pages match your brand, without custom CSS.' => 'Prilagodite svoje strani za plačilo tako, da bodo v skladu z vašo blagovno znamko, brez uporabe lastnega CSS-ja.','Change the style of the header, footer, steps, sections, order summary, cart items and coupons.' => 'Spremenite slog glave, noge, korakov, oddelkov, povzetka naročila, artiklov v košarici in kuponov.','Change the style of buttons and form fields.' => 'Spremenite videz gumbov in polj v obrazcu.','Preview your changes on checkout, cart, thank you, and order pay pages before saving them.' => 'Pred shranjevanjem si oglejte predogled sprememb na straneh za zaključek nakupa, košarici, zahvali in plačilu naročila.','Set separate colors for light and dark mode.' => 'Nastavite ločene barve za svetli in temni način.','Design' => 'Oblikovanje','Some changes to the database are required.' => 'Potrebne so nekatere spremembe v bazi podatkov.','New settings page 🎉' => 'Nova stran z nastavitvami 🎉','Fluid Checkout has a redesigned settings experience with guided setup, live page previews, and easier navigation. Open settings to explore the new layout and discover new ways to configure your checkout.' => 'Fluid Checkout ponuja prenovljeno okolje za nastavitve z vodeno nastavitvijo, predogledom strani v realnem času in enostavnejšo navigacijo. Odprite nastavitve, da si ogledate novo postavitev in odkrijete nove načine za konfiguracijo vašega postopka plačila.','Go to settings' => 'Pojdi v nastavitve','Since Fluid Checkout 5.0, settings are saved differently. Your settings have been migrated but legacy options are still stored in the database.' => 'Od različice Fluid Checkout 5.0 naprej se nastavitve shranjujejo na drugačen način. Vaše nastavitve so bile prenesene, vendar so stare možnosti še vedno shranjene v bazi podatkov.','Your store has been running for at least 2 months on the new settings so these legacy options can now be cleaned from the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Vaša trgovina deluje z novimi nastavitvami že vsaj 2 meseca, zato je zdaj mogoče te stare možnosti izbrisati iz baze podatkov. Upoštevajte, da bo v primeru, če boste po izbrisu želeli vrniti v prejšnje različice vtičnika, ta za vse nastavitve uporabil privzete vrednosti.','Fluid Checkout legacy settings cleanup' => 'Čiščenje starih nastavitev funkcije »Fluid Checkout«','Usage tracking is optional and off by default. It helps us improve compatibility and support. You can preview the exact data before it is sent, and turn it off at any time.' => 'Sledenje uporabi je neobvezno in privzeto izklopljeno. To nam pomaga izboljšati združljivost in podporo. Pred pošiljanjem si lahko ogledate natančne podatke in to funkcijo kadarkoli izklopite.','When you turn it on, Fluid Checkout receives your site domain and basic environment details: WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions. You can also choose to include monthly order counts and sales totals. No customer or user data is ever sent.' => 'Ob zagonu Fluid Checkout pridobi domeno vaše spletne strani in osnovne podatke o okolju: različice WordPressa, PHP-ja in WooCommercea, jezik, državo trgovine, valuto in časovni pas, vašo aktivno temo ter nameščene vtičnike in njihove različice. Po želji lahko vključite tudi mesečno število naročil in skupne zneske prodaje. Podatki o strankah ali uporabnikih se nikoli ne pošiljajo.','Keep it OFF' => 'Naj ostane IZKLOPLJENO','Review usage tracking' => 'Pregled sledenja uporabe','Turn on usage tracking' => 'Vklopite sledenje uporabe','Design customizations without code' => 'Prilagajanje oblikovanja brez programiranja','Express checkout from supported payment methods' => 'Hitro plačilo prek podprtih načinov plačila','Choose a color for %s' => 'Izberi barvo za %s','Clear %s' => 'Izbriši %s','Clear' => 'Izbriši','Enter a valid CSS value.' => 'Vnesite veljavno vrednost CSS.','Get faster support and help us improve compatibility and measure impact. Usage tracking is optional and off by default. <a href="%s">Review usage tracking</a> in the tools settings. You can preview the data and turn it off at any time.' => 'Zagotovite si hitrejšo podporo in nam pomagajte izboljšati združljivost ter meriti učinek. Sledenje uporabi je neobvezno in privzeto izklopljeno. <a href="%s">Preglejte nastavitve sledenja uporabi</a> v nastavitvah orodij. Podatke si lahko kadarkoli ogledate in sledenje uporabi kadarkoli izklopite.','Preview data' => 'Predogled podatkov','General styles for the checkout steps, order summary and other sections. Applies to the checkout and add payment method pages. With PRO, also applies to the cart, order pay, thank you (order received) and view order pages.' => 'Splošni slogi za korake v postopku plačila, povzetek naročila in druge razdelke. Velja za strani za zaključek nakupa in dodajanje načina plačila. V različici PRO velja tudi za strani košarice, plačila naročila, zahvale (prejeto naročilo) in pregleda naročila.','Color scheme' => 'Barvna shema','Use the light or dark colors on the checkout pages, or use the dark colors only when the theme is in dark mode.' => 'Na straneh za plačilo uporabite svetle ali temne barve, oziroma uporabite temne barve le, kadar je tema v temnem načinu.','Theme' => 'Tema','Light' => 'Svetloba','Dark' => 'Temno','Change the checkout layout to multi-step to see these options.' => 'Če želite videti te možnosti, spremenite postavitev blagajne na večstopenjsko.','Display the checkout progress bar' => 'Prikaži kazalnik napredka pri plačilu','Customers can create an account from checkout while placing their order.' => 'Stranke lahko ob oddaji naročila ustvarijo račun v okviru postopka plačila.','Help guests finish checkout faster and create an account after they buy. Account matching associates guest orders with existing accounts, and delayed account creation lets customers register from the thank you page.' => 'Pomagajte gostom, da hitreje zaključijo nakup in si po nakupu ustvarijo račun. Funkcija usklajevanja računov poveže naročila gostov z obstoječimi računi, funkcija odložene ustvaritve računa pa strankam omogoča, da se registrirajo na strani z zahvalo.','Configure customer account options' => 'Nastavite možnosti uporabniškega računa','The change could not be saved. Please try again.' => 'Spremembe ni bilo mogoče shraniti. Poskusite še enkrat.','Settings navigation' => 'Navigacija po nastavitvah','This setting has moved to %s.' => 'Ta nastavitev je bila premaknjena v %s.','another page' => 'druga stran','Dismiss the message of %s' => 'Zaprite sporočilo %s','Dismissed.' => 'Zavrnjeno.','Undo?' => 'Razveljaviti?','Optional, and off by default. It helps us improve compatibility and provide you with faster support. You can preview the exact data before it is sent, and turn it off at any time. No customer or user data is ever sent.' => 'To je neobvezna funkcija, ki je privzeto izklopljena. Pomaga nam izboljšati združljivost in vam zagotoviti hitrejšo podporo. Pred pošiljanjem si lahko ogledate natančne podatke in to funkcijo kadarkoli izklopite. Podatki o strankah ali uporabnikih se nikoli ne pošiljajo.','Nothing is sent right away unless you choose to send it. After that, usage data is sent about once a week, or about every 4 weeks if nothing has changed.' => 'Nič se ne pošlje takoj, razen če se za to odločite. Nato se podatki o uporabi pošiljajo približno enkrat na teden ali pa približno vsake 4 tedne, če se ni nič spremenilo.','Basic environment' => 'Osnovno okolje','Included whenever usage tracking is on. WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions, including whether each plugin is active. Also your site domain, whether this is a multisite, and when Fluid Checkout plugins were first activated. A paid Fluid Checkout plugin can include a hashed license key, not the key itself.' => 'Podatki se zbirajo, kadar je sledenje uporabe vklopljeno. Različice WordPressa, PHP-ja in WooCommerce-a, jezik, država trgovine, valuta in časovni pas, vaša aktivna tema ter nameščeni vtičniki in njihove različice, vključno s podatkom, ali je posamezni vtičnik aktiven. Prav tako se zbirajo podatki o domeni vaše spletne strani, o tem, ali gre za večstransko spletno mesto, ter o tem, kdaj so bili vtičniki Fluid Checkout prvič aktivirani. Plačljiva vtičnica Fluid Checkout lahko vsebuje heširan licenčni ključ, ne pa samega ključa.','The active Fluid Checkout settings you have selected.' => 'Aktivne nastavitve Fluid Checkout, ki ste jih izbrali.','These settings are not sent yet.' => 'Te nastavitve še niso bile poslane.','Store totals' => 'Skupni zneski v trgovini','Monthly order counts and sales totals for processing and completed orders, for finished months only. The first send can include the 12 months before you installed Fluid Checkout and each finished month since then. No customer or order details are included.' => 'Število mesečnih naročil in skupni zneski prodaje za naročila v obdelavi in zaključena naročila, in sicer izključno za zaključene mesece. Prvo pošiljanje lahko vključuje 12 mesecev pred namestitvijo Fluid Checkout ter vsak zaključen mesec od takrat naprej. Podatki o strankah ali naročilih niso vključeni.','Legacy settings' => 'Stare nastavitve','Since Fluid Checkout 5.0, settings are stored in profiles. Legacy individual option rows may still exist in the database from older versions to allow downgrades to a pre-5.0 plugin version.' => 'Od različice Fluid Checkout 5.0 naprej se nastavitve shranjujejo v profilih. V bazi podatkov lahko še vedno obstajajo stare vrstice s posameznimi možnostmi iz prejšnjih različic, da se omogoči prehod na starejšo različico vtičnika, ki je starejša od različice 5.0.','Legacy settings cleanup' => 'Čiščenje starih nastavitev','Remove leftover individual option rows after you no longer need to downgrade to a pre-5.0 plugin version.' => 'Odstranite preostale vrstice z individualnimi nastavitvami, ko ne boste več potrebovali prehoda na starejšo različico vtičnika, ki je starejša od 5.0.','Clean legacy settings' => 'Počisti stare nastavitve','Address book integration' => 'Povezava z imenikom','VAT number' => 'Številka DDV','Define limit of VAT Numbers a customer can save to their account.' => 'Določite omejitev števila številk DDV, ki jih lahko stranka shrani na svoj račun.','One per account' => 'Ena na račun','One per address entry' => 'Ena na vsak naslovni vnos','Usage data preview' => 'Predogled podatkov o uporabi','This is the exact usage data that would be sent with your current choices.' => 'To so natančni podatki o uporabi, ki bi bili poslani ob vaših trenutnih izbirah.','Loading preview...' => 'Nalaganje predogleda...','Could not load the preview. Try again.' => 'Predogled ni bil naložen. Poskusite znova.','Could not send the usage data. Try again.' => 'Podatkov o uporabi ni bilo mogoče poslati. Poskusite znova.','Usage data sent.' => 'Podatki o uporabi so bili poslani.','Turn on and send now' => 'Vklopite in pošljite zdaj','Usage data is already being sent. Try again in a moment.' => 'Podatki o uporabi se že pošiljajo. Poskusite čez nekaj trenutkov.','Usage tracking is turned off.' => 'Sledenje uporabi je izklopljeno.','There is no usage data to send.' => 'Ni podatkov o uporabi, ki bi jih bilo treba poslati.','This site cannot send usage data. Local and development sites are excluded.' => 'Ta spletna stran ne more pošiljati podatkov o uporabi. Izključene so lokalne in razvojne spletne strani.','Usage data was sent recently. Try again later.' => 'Podatki o uporabi so bili pred kratkim poslani. Poskusite kasneje.','The usage data could not be sent. Try again later.' => 'Podatkov o uporabi ni bilo mogoče poslati. Poskusite kasneje.','Usage tracking is not available.' => 'Sledenje uporabi ni na voljo.','There is no usage data for these choices.' => 'Za te možnosti ni podatkov o uporabi.','You are not allowed to manage usage tracking.' => 'Upravljanje sledenja uporabe vam ni dovoljeno.','Get only this add-on' => 'Pridobite samo ta dodatek','Usage tracking is turned off by the %s constant in wp-config.php.' => 'Sledenje uporabi je onemogočeno s konstanto %s v datoteki wp-config.php.','Physical products' => 'Fizični izdelki','Downloads & Digital products' => 'Prenosi in digitalni izdelki','Services' => 'Storitve','Bookings' => 'Rezervacije','Subscriptions' => 'Naročnine','Memberships' => 'Članstva','Shipping to address' => 'Dostava na naslov','Pickup in store or at a location' => 'Prevzem v trgovini ali na določeni lokaciji','Ship to pickup point' => 'Pošlji na prevzemno mesto','Local delivery' => 'Dostava na lokalnem območju','DTC - Direct to consumer' => 'DTC – Neposredna prodaja potrošnikom','B2B - To businesses' => 'B2B – Za podjetja','your country' => 'vaša država','Only in %s' => 'Samo v %s','Multiple countries' => 'Več držav','Fashion, apparel, and accessories' => 'Moda, oblačila in modni dodatki','Health and beauty' => 'Zdravje in lepota','Electronics and computers' => 'Elektronika in računalniki','Food and drink' => 'Hrana in pijača','Home, furniture, and garden' => 'Dom, pohištvo in vrt','Education and learning' => 'Izobraževanje in učenje','Sports and recreation' => 'Šport in rekreacija','Arts and crafts' => 'Umetnost in ročna dela','Other' => 'Drugo','Please select what type of products or services you sell.' => 'Prosimo, izberite, kakšne vrste izdelkov ali storitev prodajate.','Please select who you sell to.' => 'Prosimo, izberite, komu prodajate.','Please select where your customers are located.' => 'Prosimo, izberite, kje se nahajajo vaši kupci.','Please enter a valid email address for the newsletter.' => 'Vnesite veljaven e-poštni naslov za prejemanje e-novic.','Please select at least one product type.' => 'Izberite vsaj eno vrsto izdelka.','Please select at least one delivery method for physical products.' => 'Prosimo, izberite vsaj en način dostave za fizične izdelke.','About your store' => 'O vaši trgovini','Products & delivery' => 'Izdelki in dostava','Recommended setup' => 'Priporočena nastavitev','Show recommendations already applied' => 'Prikaži že uporabljena priporočila','Hide recommendations already applied' => 'Skrij že uporabljena priporočila','Show more recommendations' => 'Prikaži več priporočil','Show fewer recommendations' => 'Prikaži manj priporočil','Welcome to Fluid Checkout!' => 'Dobrodošli v Fluid Checkout!','It is great to have you here with us! We will be guiding you through the setup process – your answers to a few questions will help us recommend checkout settings for your store.' => 'Veseli nas, da ste tu z nami! Vodili vas bomo skozi postopek nastavitve – vaši odgovori na nekaj vprašanj nam bodo pomagali priporočiti ustrezne nastavitve blagajne za vašo trgovino.','What type of products or services do you sell?' => 'Kakšne izdelke ali storitve prodajate?','Who do you predominantly sell to?' => 'Komu predvsem prodajate?','Where are your customers located?' => 'Kje se nahajajo vaši kupci?','Help improve Fluid Checkout with optional usage tracking (no customer data).' => 'Pomagajte izboljšati storitev Fluid Checkout z izbirnim sledenjem uporabe (brez podatkov o strankah).','You can review and change this anytime under Tools → Usage tracking.' => 'To lahko kadarkoli pregledate in spremenite v meniju Orodja → Sledenje uporabi.','Email address' => 'E-poštni naslov','Newsletter opt-in' => 'Prijava na e-novice','Opt-in to receive news about new features, tips and recommendations from the Fluid Checkout team directly in your inbox.' => 'Prijavite se, da boste novice o novih funkcionalnostih, nasvetih in priporočilih ekipe Fluid Checkout prejemali neposredno v svoj e-poštni predal.','What do you sell, and how do you deliver physical products?' => 'Kaj prodajate in kako dostavljate fizične izdelke?','What do you sell?' => 'Kaj prodajate?','How do you handle delivery of your products?' => 'Kako urejate dostavo svojih izdelkov?','Recommended checkout settings' => 'Priporočene nastavitve za zaključek nakupa','No more recommendations to apply.' => 'Ni več priporočil, ki bi jih bilo treba upoštevati.','Show already applied' => 'Prikaži že uporabljene','Based on what you told us, these checkout options are a good starting point. You can turn recommended options off before applying them.' => 'Glede na to, kar ste nam povedali, so te možnosti plačila dobra izhodiščna točka. Priporočene možnosti lahko izklopite, preden jih uporabite.','You can change any of these settings later in the Fluid Checkout settings.' => 'Vse te nastavitve lahko kasneje spremenite v nastavitvah Fluid Checkout.','Apply settings & finish setup' => 'Uporabi nastavitve in zaključi nastavitev','Your recommended setup options have been applied.' => 'Priporočene nastavitve so bile uporabljene.','Test your checkout process and return to Fluid Checkout settings to adjust any settings if needed.' => 'Preizkusite postopek plačila in se vrnite v nastavitve Fluid Checkout, da po potrebi prilagodite nastavitve.','You can use the built-in live preview in settings to see how settings changes affect your checkout before saving them.' => 'V nastavitvah lahko uporabite vgrajeni predogled v realnem času, da pred shranjevanjem preverite, kako spremembe nastavitev vplivajo na vaš postopek plačila.','If you need help, <a href="%s" target="_blank" rel="noopener noreferrer">contact our support team</a>.' => 'Če potrebujete pomoč, <a href="%s" target="_blank" rel="noopener noreferrer">se obrnite na našo službo za podporo uporabnikom</a>.','Subscription account creation' => 'Ustvarjanje naročniškega računa','Allow subscription customers to create an account during checkout' => 'Omogočite naročnikom, da si med zaključevanjem nakupa ustvarijo račun','Enable account creation at checkout for subscription purchases when account creation for other orders is disabled.' => 'Omogoči ustvarjanje računa ob zaključku nakupa za nakupe z naročnino, kadar je ustvarjanje računa za druga naročila onemogočeno.','Multi-step checkout' => 'Večstopenjski postopek plačila','Clear steps with few fields at a time to guide customers through checkout and keep them focused.' => 'Jasni koraki z le nekaj polji naenkrat, ki stranke vodijo skozi postopek plačila in ohranjajo njihovo pozornost.','Single-step checkout' => 'Plačilo v enem koraku','Show all fields at once. Ideal for short checkouts such as digital products or services that don\'t require much information.' => 'Prikaži vsa polja hkrati. Idealno za hitre nakupe, kot so digitalni izdelki ali storitve, za katere ni potrebnih veliko podatkov.','Keep theme header and footer' => 'Ohrani glavo in nogo teme','Show the store header and footer at checkout instead of the distraction-free layout. Useful for B2B stores that need site navigation during checkout.' => 'Pri zaključku nakupa prikaži glavo in nogo spletne trgovine namesto postavitve brez motečih elementov. To je koristno za B2B-trgovine, ki med zaključkom nakupa potrebujejo navigacijo po spletnem mestu.','Edit cart at checkout' => 'Uredi košarico ob zaključku nakupa','Let customers change quantities and remove items without leaving checkout.' => 'Omogočite strankam, da spreminjajo količine in odstranjujejo izdelke, ne da bi zapustili postopek plačila.','Billing before shipping' => 'Izstavitev računa pred odpremo','Collect the billing address as a step before shipping so business buyers can enter invoice details first.' => 'Zberite naslov za izstavitev računa kot korak pred odpošiljanjem, da lahko poslovni kupci najprej vnesete podatke za račun.','Shipping methods before address' => 'Načini dostave pred vnosom naslova','Show shipping methods before the address so customers can see other delivery options such as local pickup.' => 'Prikaži načine dostave pred naslovom, da bodo stranke lahko videle druge možnosti dostave, kot je prevzem na kraju samem.','Shipping methods after address' => 'Načini dostave glede na naslov','Ask for the shipping address first, then show shipping methods that match that destination.' => 'Najprej vprašajte za naslov za dostavo, nato pa prikažite načine dostave, ki ustrezajo tej destinaciji.','Require billing company' => 'Zahteva se podjetje za izstavljanje računov','Make the billing company field required so invoices include a company name for business orders.' => 'Nastavite polje »Podjetje za izstavitev računa« kot obvezno, da bodo računi za poslovna naročila vsebovali ime podjetja.','Hide additional order notes' => 'Skrij dodatne opombe k naročilu','Hide the additional order notes field to keep checkout shorter. Customers rarely need it for most orders.' => 'Skrijte polje za dodatne opombe k naročilu, da bo postopek plačila krajši. Stranke ga pri večini naročil redko potrebujejo.','Enable optimized cart page' => 'Omogoči optimizirano stran košarice','Improved cart page to reduce cart abandonment rates and give customers a consistent experience.' => 'Izboljšali smo stran z nakupovalno košarico, da bi zmanjšali število opuščenih nakupov in strankam zagotovili dosledno izkušnjo.','Enable optimized thank you page' => 'Omogoči optimizirano stran z zahvalo','Improved thank you page to give customers a consistent experience.' => 'Izboljšana stran z zahvalo, ki strankam zagotavlja enotno izkušnjo.','Enable optimized order pay page' => 'Omogoči optimizirano stran za plačilo naročila','Improved order pay page to give customers a consistent experience.' => 'Izboljšali smo stran za plačilo naročila, da bi strankam zagotovili enotno izkušnjo.','Suggest verified addresses as customers type to reduce typos and failed deliveries.' => 'Medtem ko stranke vnašajo naslove, jim predlagajte preverjene naslove, da zmanjšate število tipkarskih napak in neuspešnih dostav.','Address book at checkout' => 'Imenik ob zaključku nakupa','Let logged-in customers pick a saved address instead of retyping it every time.' => 'Omogočite prijavljenim strankam, da izberejo shranjeni naslov, namesto da ga morajo vsakič znova vnašati.','Let customers place orders without creating an account first.' => 'Omogočite strankam, da oddajo naročila, ne da bi morali najprej ustvariti račun.','Require account to checkout' => 'Za zaključek nakupa je potreben račun','Turn off guest checkout so customers must log in or create an account before placing an order.' => 'Onemogočite nakup kot gost, tako da se morajo stranke pred oddajo naročila prijaviti ali ustvariti račun.','Login reminder at checkout' => 'Opomnik za prijavo ob zaključku nakupa','Offer a login link at checkout so returning customers can reuse saved details faster.' => 'Pri zaključku nakupa ponudite povezavo za prijavo, da bodo stalni kupci lahko hitreje ponovno uporabili shranjene podatke.','Account matching at checkout' => 'Usklajevanje računov ob plačilu','Detect when the email already belongs to an account and prompt the customer to log in instead of creating a duplicate.' => 'Ugotovite, ali je e-poštni naslov že povezan z določenim računom, in stranko pozovite, naj se prijavi, namesto da ustvari podvojen račun.','Local pickup or in-store collection' => 'Osebni prevzem ali prevzem v trgovini','Let customers choose at checkout where to pick up their order.' => 'Omogočite strankam, da ob zaključku nakupa izberejo, kje bodo prevzele svoje naročilo.','Optional shipping phone' => 'Izbirna telefonska številka za dostavo','Show a shipping phone field customers can fill when carriers or delivery partners need a contact number.' => 'Prikaži polje za telefonsko številko za dostavo, ki ga lahko stranke izpolnijo, kadar prevozniki ali partnerji za dostavo potrebujejo kontaktno številko.','Require shipping phone' => 'Zahteva se telefonska številka za dostavo','Require a phone number on the shipping address for delivery coordination and failed-delivery recovery.' => 'Na naslovu za dostavo je treba navesti telefonsko številko za usklajevanje dostave in reševanje primerov neuspešne dostave.','International phone fields' => 'Polja za mednarodne telefonske številke','Show country-aware phone inputs so customers can enter numbers in the correct international format.' => 'Prikaži polja za vnos telefonskih številk, ki upoštevajo državo, da lahko stranke številke vnašajo v pravilnem mednarodnem formatu.','Button label for applying coupon codesApply' => 'Uporabi','Checkout step titleContact' => 'Pišite na','Checkout step titleShipping' => 'Dostava','Checkout step titleBilling' => 'Obračunavanje','Checkout step titlePayment' => 'Plačilo','Checkout substep change link labelChange' => 'Sprememba','Checkout substep save link labelSave changes' => 'Shranjevanje sprememb','Substep review textNone.' => 'Ni.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Slika ni izbrana.','Settings sectionCart' => 'Voziček','Settings sectionOrder pay' => 'Plačilo naročila','Settings sectionThank you' => 'Hvala.','Settings section titleIntegrations' => 'Integracije','Settings section titleLicense keys' => 'Licenčni ključi','Captcha positionBefore place order section' => 'Pred oddajo naročila','Captcha positionBefore place order button' => 'Pred gumbom za naročilo','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Zapri','Log in link label at checkout contact stepLog in' => 'Prijavite se','Log in separator label at for when guest checkout is disabledOr continue below' => 'Ali nadaljujte spodaj','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Ali nadaljujte kot gost','Clear image selection on admin pages.Remove image' => 'Odstranitev slike','shipping packagesShipping %d' => 'Dostava %d','shipping packagesShipping' => 'Dostava','Used as fallback for "Proceed to next step" button labelnext step' => 'naslednji korak','Substep review checkbox valueYes' => 'Da','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'John','Dummy customer last name in the admin previewDoe' => 'Doe','Dummy customer company in the admin previewExample Company' => 'Primer podjetja','Dummy customer street address in the admin preview123 Main Street' => '123 Glavna ulica','Dummy customer city in the admin previewAnytown' => 'Kakršno koli mesto','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Paket prosim pustite pred vhodnimi vrati.','Dummy product name in the admin previewBeanie' => 'Kapa','Dummy product name in the admin previewCap' => 'Pokrovček','Dummy product name in the admin previewT-Shirt' => 'Majica','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Prejeli smo vaše naročilo in vam bomo poslali obvestilo, ko bo odposlano.','Dummy download in the admin previewUser guide' => 'Navodila za uporabo','Google Places API versionsPlaces API (New)' => 'API za kraje (novo)','Google Places API versionsPlaces API (Legacy)' => 'API za kraje (stara različica)','Brasil API versionsVersion 1' => 'Različica 1','Brasil API versionsVersion 2' => 'Različica 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
✔ Manage your payment preferences
✔ View order status and history' => '✔ Naslednjič hitrejše plačilo
✔ Upravljanje nastavitev plačil
✔ Pregled stanja in zgodovine naročil','VAT number field visibilityHidden' => 'Skrito','VAT number field visibilityOptional' => 'Neobvezno','VAT number field visibilityRequired' => 'Obvezno','Delivery typeShipping to address' => 'Dostava na naslov','Delivery typeLocal pickup' => 'Osebni prevzem',] ];